"""Generate tests/data/bigger.c: a deterministic ~4500-line C program (many
functions, a tree, a dispatch table) so that gcc's cc1 does real work in
tests/preload_smoke.sh.  Usage: python3 -I tests/data/gen_bigger.py > tests/data/bigger.c"""
import random
import sys

r = random.Random(7)
out = []
out.append("/* tests/data/bigger.c -- generated by tests/data/gen_bigger.py (deterministic);\n"
           " * compiled with gcc -O2 by tests/preload_smoke.sh, its output is diffed.\n"
           " * Do not edit by hand. */\n")
out.append("#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n\n")
out.append("typedef struct node { struct node *l, *r; uint64_t key; char name[24]; } node;\n")
out.append("static node *ins(node *t, uint64_t k) { if (!t) { node *n = calloc(1, sizeof *n); n->key = k; snprintf(n->name, sizeof n->name, \"n%llu\", (unsigned long long)k); return n; } if (k < t->key) t->l = ins(t->l, k); else if (k > t->key) t->r = ins(t->r, k); return t; }\n")
out.append("static uint64_t walk(node *t) { return t ? walk(t->l) * 31 + t->key + walk(t->r) : 7; }\n")
out.append("static void drop(node *t) { if (t) { drop(t->l); drop(t->r); free(t); } }\n\n")
N = 300
for i in range(N):
    a, b, c = r.randrange(1, 100), r.randrange(1, 100), r.randrange(2, 9)
    out.append(f"static uint64_t f{i}(uint64_t x)\n{{\n    uint64_t acc = {a}u;\n")
    out.append(f"    for (int i = 0; i < {c}; i++) {{\n")
    for j in range(6):
        op = r.choice(["acc = acc * {k}u + x;", "acc ^= acc >> {s};", "x = x * {k}u ^ acc;",
                       "acc += (x << {s}) | {k}u;", "if (acc & {k}u) acc -= x; else acc += {k}u;"])
        out.append("        " + op.format(k=r.randrange(3, 99991), s=r.randrange(1, 31)) + "\n")
    out.append("    }\n")
    if i > 0:
        out.append(f"    return acc + (x & 1 ? f{r.randrange(0, i)}(x >> 3) : {b}u);\n}}\n\n")
    else:
        out.append(f"    return acc + {b}u;\n}}\n\n")
out.append("typedef uint64_t (*fn_t)(uint64_t);\nstatic const fn_t table[] = {\n")
out.append(",\n".join("    f%d" % i for i in range(N)))
out.append("\n};\n\n")
out.append("""int main(void)
{
    node *t = NULL;
    uint64_t h = 1469598103934665603ull;
    for (int i = 0; i < 20000; i++) {
        uint64_t k = table[i % (int)(sizeof table / sizeof table[0])]((uint64_t)i) % 100000;
        t = ins(t, k);
        h = (h ^ k) * 1099511628211ull;
    }
    char *buf = malloc(1 << 20);
    size_t len = 0;
    for (int i = 0; i < 5000 && len < (1u << 20) - 64; i++) len += (size_t)snprintf(buf + len, 64, "%d,", i * 7);
    printf("hash %llu walk %llu len %zu\\n", (unsigned long long)h, (unsigned long long)walk(t), len);
    free(buf);
    drop(t);
    return 0;
}
""")
sys.stdout.write("".join(out))
